import "./template-editor.css";
import { readEntitlements } from "@/lib/entitlements";
import { resolveFreeTemplate } from "@/lib/template-policy";
import { TemplateControls } from "@/components/template-controls";
import { FeatureLock } from "@/components/feature-lock";
import { TemplatesFreeView } from "@/components/templates/TemplatesFreeView";
import { HighlightedText } from "@/components/templates/HighlightedText";
import styles from "@/components/templates/templates.module.css";
import { TemplatesPremiumView } from "@/components/templates/TemplatesPremiumView";
import { ArrowLeft } from "lucide-react";
import type { Prisma } from "@/generated/prisma/client";
import { Suspense } from "react";
import { TemplatesLoading } from "@/components/templates-loading";
import Link from "next/link";
import { requireUser } from "@/lib/session";
import { db } from "@/lib/db";
import { PageHeading, EmptyState } from "@/components/common";
import { TemplateForm, DeleteButton } from "@/components/forms";
import { Pagination } from "@/components/pagination";
import { pageNumber } from "@/lib/params";
export const metadata = { title: "Templates" };
async function TemplatesContent({
  searchParams,
}: {
  searchParams: Promise<{
    edit?: string;
    page?: string;
    q?: string;
    new?: string;
  }>;
}) {
  const user = await requireUser();
  const access = await readEntitlements(user.id);
  const freeTemplateId = await resolveFreeTemplate(db, user.id);
  const params = await searchParams;
  const page = pageNumber(params.page);
  const where = { userId: user.id, archivedAt: null };
  const free = access.limits.savedTemplates !== null;
  const paidLibrary = access.paidGatingEnabled && !free;
  const pageSize = paidLibrary ? 10 : 20;
  const q = paidLibrary ? (params.q ?? "").trim().slice(0, 160) : "";
  const listedWhere: Prisma.TemplateWhereInput =
    free && freeTemplateId
      ? { ...where, id: { not: freeTemplateId } }
      : { ...where };
  if (paidLibrary && q)
    listedWhere.OR = [
      { name: { contains: q, mode: "insensitive" } },
      { subject: { contains: q, mode: "insensitive" } },
    ];
  const [templates, total, editing, contacts, activeFreeTemplate] =
    await Promise.all([
      db.template.findMany({
        where: listedWhere,
        orderBy: [{ createdAt: "desc" }, { id: "desc" }],
        take: pageSize,
        skip: (page - 1) * pageSize,
        select: { id: true, name: true, subject: true, body: true },
      }),
      db.template.count({ where: paidLibrary ? listedWhere : where }),
      params.edit
        ? db.template.findFirst({ where: { ...where, id: params.edit } })
        : null,
      !paidLibrary || params.edit || params.new === "1"
        ? db.contact.findMany({
            where: { userId: user.id, archivedAt: null },
            select: {
              id: true,
              name: true,
              email: true,
              company: true,
              jobRole: true,
            },
            orderBy: { name: "asc" },
          })
        : [],
      free && freeTemplateId
        ? db.template.findFirst({
            where: { ...where, id: freeTemplateId },
            select: { id: true, name: true, subject: true, body: true },
          })
        : null,
    ]);
  const listedTotal = activeFreeTemplate ? Math.max(0, total - 1) : total;
  // Keep the editor mounted when refreshed access locks a retained template,
  // so an unsaved draft survives the upgrade prompt.
  const showEditor =
    !!editing ||
    access.limits.savedTemplates === null ||
    total < access.limits.savedTemplates;
  const query: Record<string, string> = {
    ...(q ? { q } : {}),
    ...(page > 1 ? { page: String(page) } : {}),
  };
  const suffix = new URLSearchParams(query).toString();
  const libraryHref = `/templates${suffix ? `?${suffix}` : ""}`;
  const editorOpen =
    !!editing || (params.new === "1" && (!free || !activeFreeTemplate));
  return (
    <div
      className={
        editorOpen
          ? "template-editor-page min-w-0 text-foreground"
          : `${styles.scope} text-foreground min-w-0`
      }
    >
      {editorOpen ? (
        <>
          <PageHeading
            eyebrow="Your workspace"
            title={editing ? "Edit template" : "New template"}
            description="Write your message and check its personal preview."
          />
          <Link
            href={libraryHref}
            className="mb-4 inline-flex min-h-11 items-center gap-2 text-sm text-link"
          >
            <ArrowLeft className="size-4" aria-hidden="true" />
            Back to templates
          </Link>
          {showEditor ? (
            <TemplateForm
              key={editing?.id ?? "new"}
              template={editing ?? undefined}
              contacts={contacts}
              freeEligible={
                editing
                  ? editing.id === freeTemplateId
                  : freeTemplateId === null
              }
              cancelHref={libraryHref}
              successHref={editing || free ? libraryHref : undefined}
              planLabel="Premium"
            />
          ) : (
            <FeatureLock
              upgradeFeature="templates"
              feature={
                editing
                  ? "Editing this retained template"
                  : "Additional saved templates"
              }
              planLabel="Premium"
            />
          )}
        </>
      ) : free ? (
        <TemplatesFreeView template={activeFreeTemplate} query={query} />
      ) : (
        <TemplatesPremiumView
          key={`${q}:${page}`}
          templates={templates}
          total={total}
          q={q}
          page={page}
          pageSize={pageSize}
          query={query}
          searchEnabled={paidLibrary}
        />
      )}
      {free && listedTotal > 0 && (
        <details className={`${styles.scope} text-foreground min-w-0 mt-8`}>
          <summary className="cursor-pointer min-h-11 text-[18px] font-semibold">
            Other saved templates{" "}
            <span className="text-xs text-body">{listedTotal} retained</span>
          </summary>
          <p className="text-[var(--tpl-muted)] mt-3 mb-5">
            Your existing templates are kept. Choose one to replace the template
            available on Free.
          </p>
          <section className="space-y-4" aria-label="Other saved templates">
            {!templates.length ? (
              <EmptyState
                title="No templates on this page"
                description="Return to the first page to see your retained templates."
                href="/templates"
                link="Back to templates"
              />
            ) : (
              templates.map((t) => (
                <article key={t.id} className="free-retained-card p-6 panel">
                  <div className="flex flex-wrap items-start justify-between gap-3">
                    <div className="min-w-0">
                      <h2 className="break-words text-xl font-semibold tracking-tight">
                        {t.name}
                      </h2>
                      <p className="mt-2 whitespace-pre-wrap break-words text-sm text-body">
                        <HighlightedText text={t.subject} />
                      </p>
                    </div>
                    <div className="free-retained-controls">
                      <TemplateControls
                        id={t.id}
                        selected={false}
                        planLabel="Premium"
                      />
                    </div>
                  </div>
                  <details className="mt-4">
                    <summary className="min-h-11 cursor-pointer content-center text-sm text-link">
                      View full template
                    </summary>
                    <p className="mt-4 whitespace-pre-wrap break-words text-sm leading-6 text-body">
                      <HighlightedText text={t.body} />
                    </p>
                  </details>
                  <div className="free-retained-export mt-3 pt-3">
                    <a
                      download
                      href={`/api/templates/${t.id}/export`}
                      className="inline-flex min-h-11 items-center text-sm text-link"
                    >
                      Download JSON
                    </a>
                    <DeleteButton id={t.id} kind="template" />
                  </div>
                </article>
              ))
            )}
            {listedTotal > pageSize && (
              <Pagination
                path="/templates"
                page={page}
                total={listedTotal}
                pageSize={pageSize}
              />
            )}
          </section>
        </details>
      )}
    </div>
  );
}

export default function Templates(
  props: Parameters<typeof TemplatesContent>[0],
) {
  return (
    <Suspense fallback={<TemplatesLoading />}>
      <TemplatesContent {...props} />
    </Suspense>
  );
}
